'use strict';
const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])), money=v=>Number(v||0).toLocaleString('ko-KR'), won=v=>money(v)+'원';
let state,boot,view='dashboard',selectedId=null,tab='overview',filters={},busy=false;
const headerSorts={};
const names={dashboard:'대시보드',customers:'거래처',orders:'수주 관리',purchases:'발주 관리',disbursements:'지급 관리',fulfillments:'납품 · 작업',invoices:'청구 관리',payments:'입금 관리',receivables:'미수금 현황',settings:'설정',help:'도움말'};
const statuses={Draft:'초안',Approved:'승인',Rejected:'반려',Cancelled:'취소',Open:'진행 중',Closed:'종료',Confirmed:'확정',Active:'배분 완료',Reversed:'배분 취소',Planned:'예정',InProgress:'진행 중',Completed:'완료'};
const types={Delivery:'납품',Installation:'설치',Programming:'프로그램 개발',Commissioning:'시운전',Inspection:'검수',Completion:'준공',Deposit:'계약금',Interim:'중도금',Final:'잔금',General:'일반',Additional:'추가'};
function toast(msg,error=false){const t=$('#toast');t.textContent=msg;t.className=error?'error':'';t.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.hidden=true,error?8000:3500)}
async function api(path,data,method){const headers={};if(data!==undefined){headers['X-ImOrder-Token']=boot.token;if(!(data instanceof FormData))headers['Content-Type']='application/json'}const options={method:method||(data===undefined?'GET':'POST'),headers,body:data===undefined?undefined:data instanceof FormData?data:JSON.stringify(data)};let r;try{r=await fetch('/api'+path,options)}catch{throw Error('프로그램에 연결할 수 없습니다. 잠시 후 다시 시도해 주세요.')}if(!r.ok){let e;try{e=await r.json()}catch{e={message:'서버 연결을 확인해 주세요.'}}if(data!==undefined&&r.status===403&&e.code==='FORBIDDEN'&&e.message==='사용자 화면에서 다시 시도해 주세요.'){let fresh;try{const response=await fetch('/api/bootstrap');if(response.ok)fresh=await response.json()}catch{}if(fresh?.token&&fresh.token!==headers['X-ImOrder-Token']){boot.token=fresh.token;headers['X-ImOrder-Token']=fresh.token;try{r=await fetch('/api'+path,options)}catch{throw Error('프로그램에 연결할 수 없습니다. 잠시 후 다시 시도해 주세요.')}if(r.ok)return r.status===204?null:r.headers.get('content-type')?.includes('json')?r.json():null;try{e=await r.json()}catch{e={message:'서버 연결을 확인해 주세요.'}}}}throw Error(e.message+(e.traceId?' (추적 '+e.traceId.slice(0,8)+')':''))}return r.status===204?null:r.headers.get('content-type')?.includes('json')?r.json():null}
async function refresh(){state=await api('/state');$('#sync').textContent='저장됨 · '+new Date(state.asOfUtc).toLocaleTimeString('ko-KR',{hour:'2-digit',minute:'2-digit'});$('#today').textContent=new Date(state.today+'T12:00:00').toLocaleDateString('ko-KR',{year:'numeric',month:'long',day:'numeric',weekday:'short'});render()}
const directPaid=id=>state.payments.filter(p=>p.orderId===id&&p.status==='Confirmed').reduce((sum,p)=>sum+p.amount,0);
const customer=id=>state.customers.find(x=>x.id===id), cname=id=>esc(customer(id)?.companyName||'—'), order=id=>state.orders.find(x=>x.id===id), fin=id=>state.financials.find(x=>x.orderId===id), activeAll=()=>state.allocations.filter(x=>x.status==='Active'), allocated=(kind,id)=>activeAll().filter(x=>x[kind+'Id']===id).reduce((a,x)=>a+x.amount,0), due=i=>i.status==='Confirmed'?i.totalAmount-allocated('invoice',i.id):0, unallocated=p=>p.status==='Confirmed'&&!p.orderId?p.amount-allocated('payment',p.id):0;
function badge(s){return `<span class="badge ${['Confirmed','Approved','Completed','Closed','Active'].includes(s)?'green':['Draft','Planned'].includes(s)?'gray':['Cancelled','Reversed','Overdue'].includes(s)?'red':'amber'}">${esc(statuses[s]||s)}</span>`}
function heading(title,sub,actions='',eyebrow='WORKSPACE'){return `<div class="eyebrow">${eyebrow}</div><div class="page-heading"><div><h1>${title}</h1><p>${sub}</p></div><div class="actions">${actions}</div></div>`}
const btn=(label,action,cls='',id='')=>`<button class="${cls}" data-action="${action}" ${id!==''?`data-id="${id}"`:''}>${label}</button>`;
const empty=(title='아직 등록된 자료가 없습니다.',sub='오른쪽 위 등록 버튼으로 첫 거래를 시작해 보세요.')=>`<div class="empty"><strong>${title}</strong>${sub}</div>`;
function table(headers,rows){return rows.length?`<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`:empty()}
function panel(title,body,action=''){return `<section class="panel"><div class="panel-head"><h2>${title}</h2>${action}</div>${body}</section>`}
function stat(label,value,sub,featured=false,unit='원'){return `<div class="stat ${featured?'featured':''}"><div class="stat-label">${label}<span>↗</span></div><div class="stat-value num">${money(value)}<small>${unit}</small></div><div class="stat-sub">${sub}</div></div>`}
function route(){const parts=location.hash.slice(1).split('/');view=names[parts[0]]?parts[0]:'dashboard';selectedId=Number(parts[1])||null;tab=parts[2]||'overview';if(state)render()}
function nav(){let html='<div class="nav-label">OVERVIEW</div>';const entries=[['dashboard','◫'],['customers','♧'],['orders','▣'],['purchases','▥'],['fulfillments','✓'],['invoices','▧'],['payments','⇄'],['disbursements','↗'],['receivables','◷'],['settings','⚙'],['help','?']];entries.forEach(([key,icon],i)=>{if(i===2)html+='<div class="nav-label">BUSINESS</div>';if(i===8)html+='<div class="nav-label">MANAGEMENT</div>';html+=`<a class="nav-item ${view===key?'active':''}" href="#${key}"><span>${icon}</span><span>${names[key]}</span>${key==='orders'?`<span class="count">${state.orders.filter(x=>x.status==='Open').length}</span>`:''}</a>`});$('#nav').innerHTML=html;$('#crumb').textContent=names[view];$('#aiContext').textContent=selectedId&&view==='orders'?'선택 수주 · '+(order(selectedId)?.number||'없음'):'현재 화면 · '+names[view]}
function render(){nav();const content=$('#content');if(view==='dashboard')content.innerHTML=dashboard();else if(view==='help')content.innerHTML=helpPage();else if(view==='disbursements')content.innerHTML=disbursementPage();else if(view==='purchases'){content.innerHTML=selectedId?purchaseDetail(selectedId):purchaseList();if(selectedId&&tab==='history')loadHistory()}else if(view==='settings'){content.innerHTML=settingsPage();loadBackups();if(typeof aiSettingsMode==='function')aiSettingsMode()}else if(selectedId&&['orders','quotations','invoices','customers','payments'].includes(view)){content.innerHTML=detail();if(tab==='history')loadHistory()}else content.innerHTML=listPage();bindFilters()}
function dashboard(){const f=state.financials.filter(x=>order(x.orderId)?.status!=='Cancelled');const sum=k=>f.reduce((a,x)=>a+x[k],0);const overdue=state.invoices.filter(i=>!directPaid(i.orderId)&&due(i)>0&&i.dueDate&&i.dueDate<state.today);const unalloc=state.payments.reduce((a,p)=>a+unallocated(p),0);const ongoing=state.orders.filter(x=>x.status==='Open').slice(0,5);return heading('오늘의 업무를 한눈에','진행 중인 수주와 청구·입금 현황을 확인하세요.',btn('＋ 수주 등록','new-order','primary')+btn('입금 등록','new-payment'),'BUSINESS OVERVIEW')+`<div class="stats dashboard-stats">${stat('전체 수주금액',sum('orderTotal'),'등록 수주 '+f.length+'건')}${stat('누적 확정 청구',sum('invoiced'),'초안과 취소 청구 제외')}${stat('전체 미수금',sum('totalRemaining'),'수주 계약금액 − 프로젝트 입금',true)}</div><div class="grid-two">${panel('수주 · 수금 흐름',`<div class="panel-body"><div class="flow"><span>수주</span><b>→</b><span>발주</span><b>→</b><span>납품·검수</span><b>→</b><span>청구</span><b>→</b><span>입금</span></div><div class="ledger"><div><span>계약금액 중 청구한 금액</span><b class="num">${sum('orderTotal')?Math.round(sum('invoiced')/sum('orderTotal')*100):0}%</b></div><div class="progress"><span style="width:${sum('orderTotal')?sum('invoiced')/sum('orderTotal')*100:0}%"></span></div><div><span>미청구 잔액</span><b class="num">${won(sum('uninvoiced'))}</b></div><div><span>거래처 미배분 입금</span><b class="num">${won(unalloc)}</b></div><div><span>전체 잔금</span><b class="num">${won(sum('totalRemaining'))}</b></div></div></div>`,`<a href="#receivables">잔액 자세히 ↗</a>`)}${panel('지급기한이 지난 청구',overdue.length?overdue.slice(0,4).map(i=>`<a class="due-item" href="#invoices/${i.id}"><span class="due-mark">!</span><div><strong>${cname(i.customerId)}</strong><small>${esc(i.number)} · ${i.dueDate}</small></div><div class="amount num">${won(due(i))}<small>미수금</small></div></a>`).join(''):empty('기한이 지난 청구가 없습니다.','확정 청구의 지급기한과 미수금을 확인합니다.'),`<a href="#receivables">전체 보기 ↗</a>`)}</div>${panel('진행 중인 수주',table(['수주 / 프로젝트','거래처','계약금액','전체 미수금','수금률','상태'],ongoing.map(o=>{const f=fin(o.id);return `<tr class="row-link" data-go="orders/${o.id}"><td><span class="cell-title">${esc(o.projectName)}</span><span class="cell-sub">${esc(o.number)}</span></td><td>${cname(o.customerId)}</td><td class="num">${won(o.totalAmount)}</td><td class="num">${won(f.totalRemaining)}</td><td><span class="cell-sub">${o.totalAmount?Math.round(f.paid/o.totalAmount*100):0}%</span><div class="progress"><span style="width:${o.totalAmount?f.paid/o.totalAmount*100:0}%"></span></div></td><td>${badge(o.status)}</td></tr>`})),`<a href="#orders">모든 수주 보기 ↗</a>`)}<p class="summary-line">이전 미연결 입금은 수주의 수금 실적에 포함되지 않습니다. 작업 완료와 청구·수금 상태는 각각 관리됩니다.</p>`}
function toolbar(){const f=filters[view]||{};return `<div class="toolbar"><input type="search" id="filterQuery" placeholder="거래처 · 문서번호 · 프로젝트 검색" value="${esc(f.query||'')}"><input aria-label="시작일" type="date" id="filterFrom" value="${esc(f.from||'')}"><span>~</span><input aria-label="종료일" type="date" id="filterTo" value="${esc(f.to||'')}"><select id="filterStatus" aria-label="상태"><option value="">모든 상태</option>${Object.entries(['purchases','disbursements'].includes(view)?{Open:'진행 중',Completed:'지급 완료',Cancelled:'취소'}:statuses).map(([k,v])=>`<option value="${k}" ${f.status===k?'selected':''}>${v}</option>`).join('')}</select><select id="filterSort" aria-label="정렬"><option value="new">최근 등록순</option><option value="date" ${f.sort==='date'?'selected':''}>일자순</option><option value="amount" ${f.sort==='amount'?'selected':''}>금액 큰 순</option></select><div class="right-actions">${['customers','quotations','orders','invoices','payments'].includes(view)?`<a href="/api/export/${view}"><button>↓ 엑셀</button></a>`:''}</div></div>`}
function filtered(rows){const f=filters[view]||{},selectedSort=headerSorts[view],sortValue=selectedSort&&headerSortConfig()[selectedSort.label];return [...rows].filter(x=>{const text=[x.companyName,x.number,x.projectName,x.description,x.reference,customer(x.customerId)?.companyName,order(x.orderId)?.projectName,x.title,customer(x.supplierId)?.companyName,order(x.salesOrderId)?.projectName].join(' ').toLowerCase();const date=x.date||x.plannedDate||x.createdAtUtc.slice(0,10);return (!f.query||text.includes(f.query.toLowerCase()))&&(!f.from||date>=f.from)&&(!f.to||date<=f.to)&&(!f.status||(['purchases','disbursements'].includes(view)?purchaseDisplayStatus(x):x.status)===f.status)}).sort((a,b)=>{const selected=selectedSort,fn=sortValue;if(fn){const av=fn(a),bv=fn(b),emptyA=av==null||av==='',emptyB=bv==null||bv==='';if(emptyA||emptyB)return emptyA===emptyB?a.id-b.id:emptyA?1:-1;const cmp=typeof av==='number'&&typeof bv==='number'?av-bv:String(av).localeCompare(String(bv),'ko',{numeric:true,sensitivity:'base'});return cmp?cmp*(selected.direction==='asc'?1:-1):a.id-b.id}if(view==='receivables'&&(!f.sort||f.sort==='new')){const priority=Number((fin(b.id)?.totalRemaining||0)>0)-Number((fin(a.id)?.totalRemaining||0)>0);if(priority)return priority}return view==='customers'&&a.isPreferred!==b.isPreferred?Number(b.isPreferred)-Number(a.isPreferred):f.sort==='amount'?(b.totalAmount||b.amount||0)-(a.totalAmount||a.amount||0):f.sort==='date'?String(a.date||a.plannedDate).localeCompare(String(b.date||b.plannedDate)):b.id-a.id})}
function projectBalance(id){const f=fin(id);return f?won(f.totalRemaining):'확인 불가'}
function paymentProjects(id){const grouped=new Map(),p=state.payments.find(x=>x.id===id);if(p?.orderId){const o=order(p.orderId);if(o)grouped.set(o.id,{orderId:o.id,name:o.projectName,amount:p.amount})}for(const a of state.allocations.filter(x=>x.paymentId===id&&x.status==='Active')){const i=state.invoices.find(x=>x.id===a.invoiceId),o=i&&order(i.orderId);if(o)grouped.set(o.id,{orderId:o.id,name:o.projectName,amount:(grouped.get(o.id)?.amount||0)+a.amount})}return [...grouped.values()]}
function listPage(){const actions={customers:['＋ 거래처 등록','new-customer'],quotations:['＋ 새 견적','new-quotation'],orders:['＋ 직접 수주 등록','new-order'],fulfillments:['＋ 작업 등록','new-fulfillment'],invoices:['＋ 청구 등록','new-invoice'],payments:['＋ 입금 등록','new-payment']};const a=actions[view];let body='';if(view==='customers')body=table(['거래처','사업자번호','담당자','연락처','사용 상태',''],filtered(state.customers).map(c=>`<tr data-go="customers/${c.id}" class="row-link"><td><span class="cell-title">${esc(c.companyName)}${c.isPreferred?' <span class="badge green">★ 주거래처</span>':''}</span><span class="cell-sub">${esc(c.code)}</span></td><td>${esc(c.businessNumber)}</td><td>${esc(c.contactName)}</td><td>${esc(c.phone)}</td><td>${`<span class="badge ${c.isActive?'green':'gray'}">${c.isActive?'사용':'사용 안 함'}</span>`}</td><td>↗</td></tr>`));else if(view==='fulfillments')body=table(['작업 내용','수주','종류','예정일','완료일','상태',''],filtered(state.fulfillments).map(w=>`<tr><td>${esc(w.description)||'—'}</td><td><a href="#orders/${w.orderId}">${esc(order(w.orderId)?.projectName)}</a></td><td>${types[w.type]}</td><td>${w.plannedDate||'—'}</td><td>${w.completedDate||'—'}</td><td>${badge(w.status)}</td><td>${btn('수정','edit-fulfillment','',w.id)} ${btn('첨부','work-attachments','',w.id)}</td></tr>`));else if(view==='payments')body=table(['입금일','거래처','연결 프로젝트','프로젝트 계약금액','입금액','프로젝트 누적 입금','전체 미수금','이전 미연결액','참조 / 은행','상태'],filtered(state.payments).map(p=>`<tr class="row-link" data-go="payments/${p.id}"><td>${p.date}</td><td>${cname(p.customerId)}</td><td>${paymentProjects(p.id).length?paymentProjects(p.id).map(x=>esc(x.name)+' · '+won(x.amount)).join('<br>'):'미연결'}${unallocated(p)>0&&paymentProjects(p.id).length?'<span class="cell-sub">미배분액 있음</span>':''}</td>${['orderTotal','paid','totalRemaining'].map(key=>`<td class="num">${paymentProjects(p.id).length?paymentProjects(p.id).map(x=>{const f=fin(x.orderId);return (paymentProjects(p.id).length>1?esc(x.name)+' · ':'')+(f?won(f[key]):'확인 불가')}).join('<br>'):'프로젝트 미연결'}</td>${key==='orderTotal'?`<td class="num">${won(p.amount)}</td>`:''}`).join('')}<td class="num">${won(unallocated(p))}</td><td>${esc(p.reference)}<span class="cell-sub">${esc(p.bankName)}</span></td><td>${badge(p.status)}</td></tr>`));else if(view==='receivables'){body=table(['수주 / 거래처','계약금액','누적 청구','프로젝트 입금','청구 미수금','미청구 잔액','전체 미수금'],filtered(state.orders).map(o=>{const f=fin(o.id);return `<tr class="row-link" data-go="orders/${o.id}"><td>${esc(o.projectName)}<span class="cell-sub">${cname(o.customerId)}</span></td>${['orderTotal','invoiced','paid','outstanding','uninvoiced','totalRemaining'].map(k=>`<td class="num">${won(f[k])}</td>`).join('')}</tr>`}));body+=panel('거래처 미배분 입금',table(['거래처','확정 입금','미배분액'],state.payments.filter(p=>unallocated(p)>0).map(p=>`<tr class="row-link" data-go="payments/${p.id}"><td>${cname(p.customerId)}</td><td>${won(p.amount)}</td><td>${won(unallocated(p))}</td></tr>`)))}else{const rows=filtered(state[view]||[]);body=table(['문서 / 프로젝트',...(view==='orders'?['수주금액','연결 발주금액','잔금']:view==='invoices'?['프로젝트 계약금액','청구금액','프로젝트 누적 입금','프로젝트 전체 미수금']:[]),'거래처',...(view==='invoices'?['청구 유형']:[]),'작성일','기한','공급가액','VAT',...(['invoices','orders'].includes(view)?[]:['합계']),view==='invoices'?'청구 상태 / 미수금':'상태'],rows.map(d=>`<tr class="row-link" data-go="${view}/${d.id}"><td><span class="cell-title">${esc(d.projectName)}</span><span class="cell-sub">${esc(d.number)}</span></td>${view==='orders'?`<td class="num">${won(d.totalAmount)}</td><td class="num">${won(linkedPurchaseAmount(d.id))}<span class="cell-sub">${linkedPurchaseOrders(d.id).length?'연결 '+linkedPurchaseOrders(d.id).length+'건':'연결 없음'}</span></td><td class="num">${won(fin(d.id)?.totalRemaining||0)}</td>`:view==='invoices'?['orderTotal','paid','totalRemaining'].map(k=>`<td class="num">${fin(d.orderId)?won(fin(d.orderId)[k]):'확인 불가'}</td>${k==='orderTotal'?`<td class="num">${won(d.totalAmount)}</td>`:''}`).join(''):''}<td>${cname(d.customerId)}</td>${view==='invoices'?`<td>${esc(types[d.invoiceType]||d.invoiceType||'—')}</td>`:''}<td>${d.date}</td><td>${d.dueDate||'—'}</td><td class="num">${money(d.supplyAmount)}</td><td class="num">${money(d.vatAmount)}</td>${['invoices','orders'].includes(view)?'':`<td class="num">${won(d.totalAmount)}</td>`}<td>${view==='invoices'?`${badge(d.status)}<span class="cell-sub ${!directPaid(d.orderId)&&due(d)>0&&d.dueDate&&d.dueDate<state.today?'money-warn':''}">${directPaid(d.orderId)?'프로젝트에서 확인':won(due(d))}${!directPaid(d.orderId)&&due(d)>0&&d.dueDate&&d.dueDate<state.today?' · 기한 경과':''}</span>`:badge(d.status)}</td></tr>`))}return heading(names[view],view==='receivables'?'전체 미수금은 계약금액에서 프로젝트 입금을 뺀 금액입니다.':'등록된 자료를 검색하고 상세 업무를 이어가세요.',a?(btn(a[0],a[1],'primary')+(view==='invoices'?btn('＋ 세금계산서로 입력','tax-invoice-import') : '')):'')+toolbar()+`<div id="listRows" class="panel">${body}</div>`}
function headerSortConfig(){
 const status=x=>statuses[x.status]||x.status||'';
 const customerName=x=>customer(x.customerId)?.companyName||'';
 const projectName=x=>order(x.orderId)?.projectName||x.projectName||'';
 const related=x=>view==='orders'||view==='receivables'?fin(x.id):view==='invoices'?fin(x.orderId):null;
 const paymentMetric=(p,key)=>{const projects=paymentProjects(p.id);return projects.length?(fin(projects[0].orderId)?.[key]??null):null};
 const doc={'문서 / 프로젝트':x=>x.projectName,'거래처':customerName,'작성일':x=>x.date,'기한':x=>x.dueDate,'공급가액':x=>x.supplyAmount,'VAT':x=>x.vatAmount,'합계':x=>x.totalAmount,'상태':status};
 if(view==='purchases'||view==='disbursements')return {'발주 / 프로젝트':x=>x.title,'공급처':purchaseSupplier,'발주일':x=>x.date,'납기':x=>x.dueDate,'발주금액':x=>x.totalAmount,'매입금액':x=>purchaseTotals(x).billed,'지급금액':x=>purchaseTotals(x).paid,'발주 잔금':x=>purchaseTotals(x).remaining,'상태':x=>purchaseDisplayStatus(x)==='Completed'?'지급 완료':status(x)};
 if(view==='customers')return {'거래처':x=>x.companyName,'사업자번호':x=>x.businessNumber,'담당자':x=>x.contactName,'연락처':x=>x.phone,'사용 상태':x=>x.isActive?'사용':'사용 안 함'};
 if(view==='payments')return {'입금일':x=>x.date,'거래처':customerName,'연결 프로젝트':x=>paymentProjects(x.id).map(p=>p.name).sort((a,b)=>a.localeCompare(b,'ko')).join(', '),'프로젝트 계약금액':x=>paymentMetric(x,'orderTotal'),'입금액':x=>x.amount,'프로젝트 누적 입금':x=>paymentMetric(x,'paid'),'전체 미수금':x=>paymentMetric(x,'totalRemaining'),'이전 미연결액':unallocated,'참조 / 은행':x=>[x.reference,x.bankName].filter(Boolean).join(' '),'상태':status};
 if(view==='fulfillments')return {'작업 내용':x=>x.description,'수주':projectName,'종류':x=>types[x.type]||x.type,'예정일':x=>x.plannedDate,'완료일':x=>x.completedDate,'상태':status};
 if(view==='receivables')return {'수주 / 거래처':x=>x.projectName,'계약금액':x=>related(x)?.orderTotal,'누적 청구':x=>related(x)?.invoiced,'프로젝트 입금':x=>related(x)?.paid,'청구 미수금':x=>related(x)?.outstanding,'미청구 잔액':x=>related(x)?.uninvoiced,'전체 미수금':x=>related(x)?.totalRemaining};
 if(view==='invoices')return {...doc,'프로젝트 계약금액':x=>related(x)?.orderTotal,'청구금액':x=>x.totalAmount,'프로젝트 누적 입금':x=>related(x)?.paid,'프로젝트 전체 미수금':x=>related(x)?.totalRemaining,'청구 유형':x=>types[x.invoiceType]||x.invoiceType,'청구 상태 / 미수금':x=>directPaid(x.orderId)?null:due(x)};
 if(view==='orders')return {...doc,'수주금액':x=>x.totalAmount,'연결 발주금액':x=>linkedPurchaseAmount(x.id),'잔금':x=>related(x)?.totalRemaining};
 return view==='quotations'?doc:{};
}
function decorateSortHeaders(){const panel=$('#listRows');if(!panel||selectedId)return;const head=panel.querySelector('.table-wrap table thead tr');if(!head)return;const config=headerSortConfig(),selected=headerSorts[view];for(const th of head.children){const label=th.textContent.trim();if(!config[label])continue;const direction=selected?.label===label?selected.direction:null;th.setAttribute('aria-sort',direction==='asc'?'ascending':direction==='desc'?'descending':'none');th.innerHTML=`<button type="button" class="sort-header" data-sort-header="${esc(label)}" aria-label="${esc(label)} 정렬${direction==='asc'?' · 오름차순':direction==='desc'?' · 내림차순':''}">${esc(label)} <span aria-hidden="true">${direction==='asc'?'▲':direction==='desc'?'▼':'↕'}</span></button>`}}
function updateListRows(){const tmp=document.createElement('div');tmp.innerHTML=view==='purchases'?purchaseList():listPage();const target=$('#listRows'),next=tmp.querySelector('#listRows');if(target&&next){target.innerHTML=next.innerHTML;decorateSortHeaders()}}
function bindFilters(){decorateSortHeaders();['Query','From','To','Status','Sort'].forEach(k=>{const el=$('#filter'+k);if(el)el.addEventListener(k==='Query'?'input':'change',()=>{if(k==='Sort')delete headerSorts[view];filters[view]={query:$('#filterQuery').value,from:$('#filterFrom').value,to:$('#filterTo').value,status:$('#filterStatus').value,sort:$('#filterSort').value};updateListRows()})})}
document.addEventListener('click',e=>{const button=e.target.closest('[data-sort-header]');if(!button)return;e.preventDefault();const label=button.dataset.sortHeader,previous=headerSorts[view];headerSorts[view]={label,direction:previous?.label===label&&previous.direction==='asc'?'desc':'asc'};updateListRows();const next=[...document.querySelectorAll('[data-sort-header]')].find(x=>x.dataset.sortHeader===label);next?.focus()});

function entityType(){return {customers:'Customer',quotations:'Quotation',orders:'SalesOrder',invoices:'Invoice',payments:'Payment',purchases:'PurchaseOrder'}[view]}
function detail(){const row=state[view].find(x=>x.id===selectedId);if(!row)return empty('자료를 찾을 수 없습니다.','목록에서 다시 선택해 주세요.');const type=entityType();let actions='';if(view==='customers')actions=btn('거래처 수정','edit-customer','',row.id)+btn('거래처 삭제','delete-customer','danger',row.id);if(view==='quotations'){if(row.status==='Draft')actions+=btn('초안 수정','edit-quotation','',row.id)+btn('견적 승인','approve-quotation','primary',row.id);if(row.status==='Approved'&&!state.orders.some(x=>x.quotationId===row.id))actions+=btn('수주로 전환','convert-quotation','primary',row.id)}if(view==='orders'&&row.status==='Open')actions+=btn('작업 등록','new-fulfillment','',row.id)+btn('청구 등록','new-invoice','primary',row.id)+btn('수주 종료','close-order','',row.id);if(view==='orders'&&row.status==='Open')actions+=btn('수주 정보 수정','order-details','',row.id)+btn('계약 변경','contract-change','',row.id);if(view==='orders'&&row.status==='Closed')actions+=btn('수주 재개','reopen-order','',row.id);if(view==='invoices'&&['Draft','Confirmed'].includes(row.status))actions+=btn('청구 수정','edit-invoice','primary',row.id);if(view==='invoices')actions+=btn('청구 삭제','delete-invoice','danger',row.id);if(view==='invoices'&&row.status==='Confirmed')actions+=btn('세금계산서 발급 기록','tax-record','',row.id);if(view==='invoices'&&row.status==='Draft')actions+=btn('청구 확정','confirm-invoice','primary',row.id);if(view==='payments'){if(['Draft','Confirmed'].includes(row.status))actions+=btn('입금 수정','edit-payment','primary',row.id);if(row.status==='Confirmed'&&!row.orderId&&unallocated(row)>0&&allocated('payment',row.id)>0)actions+=btn('이전 입금 연결','allocate','primary',row.id)}if(['quotations','invoices','payments'].includes(view)&&row.status!=='Cancelled'&&!state.orders.some(x=>view==='quotations'&&x.quotationId===row.id))actions+=btn('취소','cancel-document','danger',row.id);if(['quotations','orders','invoices'].includes(view))actions+=`<a target="_blank" rel="noopener" href="/api/print/${type}/${row.id}"><button>인쇄 / PDF</button></a>`;let html=`<a class="back" href="#${view}">← ${names[view]} 목록</a>`+heading(esc(row.projectName||row.companyName||'입금 상세'),`${esc(row.number||row.code||row.date)}　${row.customerId?cname(row.customerId):''}　${row.status?badge(row.status):''}`,actions,'DOCUMENT DETAIL');if(view==='orders'){const f=fin(row.id);html+=`<div class="stats">${stat('수주 계약금액',f.orderTotal,'공급 '+money(row.supplyAmount)+' · VAT '+money(row.vatAmount))}${stat('누적 청구',f.invoiced,'미청구 '+won(f.uninvoiced))}${stat('프로젝트 입금',f.paid,'전체 잔금 '+won(f.totalRemaining))}${stat('전체 미수금',f.totalRemaining,'수주 계약금액 − 프로젝트 입금',true)}</div>`}else if(view==='invoices'||view==='quotations')html+=`<div class="stats">${stat('공급가액',row.supplyAmount,'원 단위 저장')}${stat('VAT',row.vatAmount,'저장 당시 정책 적용')}${stat('합계',row.totalAmount,'부가세 포함',true)}${view==='invoices'?(directPaid(row.orderId)?`<div class="stat"><div class="stat-label">청구 미수금</div><div class="stat-sub">프로젝트 단위로 확인</div></div>`:stat('청구 미수금',due(row),'확정 청구에만 적용')):stat('견적 품목',JSON.parse(row.itemsJson).length,'품목 수',false,'개')}</div>`;if(view==='invoices'&&fin(row.orderId)){const f=fin(row.orderId);html+=`<div class="stats">${stat('프로젝트 계약금액',f.orderTotal,'부가세 포함')}${stat('프로젝트 누적 입금',f.paid,'현재까지 연결된 전체 입금')}${stat('프로젝트 전체 미수금',f.totalRemaining,'계약금액 − 누적 입금',true)}</div>`}else if(view==='payments')html+=`<div class="stats">${stat('입금액',row.amount,row.date)}${row.orderId&&fin(row.orderId)?stat('프로젝트 계약금액',fin(row.orderId).orderTotal,'부가세 포함 전체 금액'):paymentProjects(row.id).length?`<div class="stat"><div class="stat-label">프로젝트별 계약금액</div>${paymentProjects(row.id).map(x=>`<div>${esc(x.name)} · ${fin(x.orderId)?won(fin(x.orderId).orderTotal):'확인 불가'}</div>`).join('')}</div>`:`<div class="stat"><div class="stat-label">프로젝트 계약금액</div><div class="stat-sub">프로젝트 연결 후 표시됩니다.</div></div>`}${row.orderId&&fin(row.orderId)?stat('프로젝트 누적 입금',fin(row.orderId).paid,'현재까지 연결된 전체 입금'):stat('프로젝트 연결 입금',allocated('payment',row.id),'이 입금의 연결 금액')}${row.orderId&&fin(row.orderId)?stat('전체 미수금',fin(row.orderId).totalRemaining,'현재 프로젝트 계약금액 − 전체 입금',true):paymentProjects(row.id).length?`<div class="stat featured"><div class="stat-label">현재 프로젝트별 전체 미수금</div>${paymentProjects(row.id).map(x=>`<div>${esc(x.name)} · ${projectBalance(x.orderId)}</div>`).join('')}</div>`:`<div class="stat"><div class="stat-label">전체 미수금</div><div class="stat-sub">프로젝트 연결 후 표시됩니다.</div></div>`}${row.orderId?'':stat('이전 미연결액',unallocated(row),'이전 방식으로 등록된 입금')}</div>`;const tabs={overview:'기본 정보',...(view==='orders'?{work:'납품 · 작업',invoices:'청구 내역',allocations:'이전 연결 내역'}:view==='payments'&&!row.orderId||view==='invoices'?{allocations:'이전 연결 내역'}:{}),attachments:'첨부파일',history:'변경 이력'};html+=`<div class="tabs">${Object.entries(tabs).map(([key,label])=>`<button class="${tab===key?'active':''}" data-go="${view}/${row.id}/${key}">${label}</button>`).join('')}</div>`;if(tab==='history')return html+panel('변경 이력','<div id="historyRows" class="empty">불러오는 중…</div>');if(tab==='attachments')return html+attachments(type,row.id);if(tab==='work')return html+workTable(row.id);if(tab==='invoices')return html+invoiceTable(row.id);if(tab==='allocations')return html+allocationTable(row);if(view==='customers'){html+=panel('거래처 정보',`<div class="panel-body info-grid">${[['상호',row.companyName],['사업자번호',row.businessNumber],['대표자',row.ceoName],['담당자',row.contactName],['연락처',row.phone],['이메일',row.email],['주소',row.address],['메모',row.memo],['업태',row.businessType],['종목',row.businessItem],['사용 여부',row.isActive?'사용':'사용 안 함'],['주거래처',row.isPreferred?'★ 주거래처':'일반 거래처']].map(([k,v])=>`<label>${k}<span>${esc(v)||'—'}</span></label>`).join('')}</div>`)}else if(view==='payments')html+=panel('입금 정보',`<div class="panel-body info-grid">${[['프로젝트',row.orderId?order(row.orderId)?.projectName:'이전 입금 · 연결 내역 확인'],['은행',row.bankName],['입금자 / 참조',row.reference],['메모',row.memo]].map(([k,v])=>`<label>${k}<span>${esc(v)||'—'}</span></label>`).join('')}</div>`)+(row.orderId?'':allocationTable(row));else{const snapshot=JSON.parse(row.snapshotJson);html+=panel('문서 정보',`<div class="panel-body info-grid">${[['문서번호',row.number],['거래처 (문서 스냅샷)',snapshot.companyName],['작성일',row.date],['기한',row.dueDate],['현장',row.siteName],['메모',row.memo]].map(([k,v])=>`<label>${k}<span>${esc(v)||'—'}</span></label>`).join('')}</div>`);const items=JSON.parse(row.itemsJson);if(items.length)html+=panel('품목 내역',table(['품목 / 규격','수량','단가','공급가액','VAT','합계'],items.map(i=>`<tr><td>${esc(i.input.description)}<span class="cell-sub">${esc(i.input.specification)} · ${esc(i.input.taxCategory)}</span></td><td>${i.input.quantity} ${esc(i.input.unit)}</td><td>${money(i.input.unitPrice)}</td><td>${money(i.supplyAmount)}</td><td>${money(i.vatAmount)}</td><td>${won(i.totalAmount)}</td></tr>`)));if(view==='orders')html+=purchaseSalesSummary(row.id)+purchaseSalesPanel(row.id)+workTable(row.id)+invoiceTable(row.id);if(view==='invoices')html+=`<div class="notice">청구유형: ${types[row.invoiceType]} · 지급기한 ${row.dueDate||'미지정'} · 외부 세금계산서 발급 ${row.taxInvoiceIssued?'기록 있음':'미확인'}${row.taxInvoiceDate?' · 작성일 '+esc(row.taxInvoiceDate):''}${row.taxApprovalNo?' · 승인번호 '+esc(row.taxApprovalNo):''}<br>내부 청구 확정은 전자세금계산서 발급과 별개입니다.</div>`}return html}
function workTable(id){return panel('납품 · 작업 · 검수',table(['내용','종류','예정일','완료일','상태',''],state.fulfillments.filter(w=>w.orderId===id).map(w=>`<tr><td>${esc(w.description)||'—'}</td><td>${types[w.type]}</td><td>${w.plannedDate||'—'}</td><td>${w.completedDate||'—'}</td><td>${badge(w.status)}</td><td>${btn('수정','edit-fulfillment','',w.id)} ${btn('첨부','work-attachments','',w.id)}</td></tr>`)),btn('＋ 등록','new-fulfillment','',id))}
function invoiceTable(id){return panel('청구 내역',table(['문서번호','유형','청구일','지급기한','합계','미수금','상태'],state.invoices.filter(i=>i.orderId===id).map(i=>`<tr data-go="invoices/${i.id}" class="row-link"><td>${esc(i.number)}</td><td>${types[i.invoiceType]}</td><td>${i.date}</td><td>${i.dueDate||'미지정'}</td><td>${won(i.totalAmount)}</td><td>${directPaid(i.orderId)?'프로젝트에서 확인':won(due(i))}</td><td>${badge(i.status)}</td></tr>`)))}
function allocationTable(row){const list=state.allocations.filter(a=>view==='payments'?a.paymentId===row.id:view==='invoices'?a.invoiceId===row.id:state.invoices.some(i=>i.id===a.invoiceId&&i.orderId===row.id));return panel('입금 배분 내역',table(['배분 ID','프로젝트','청구번호','입금일','금액','상태',''],list.map(a=>{const i=state.invoices.find(i=>i.id===a.invoiceId),p=state.payments.find(p=>p.id===a.paymentId);return `<tr><td>#${a.id}</td><td>${esc(i?(order(i.orderId)?.projectName||i.projectName):'삭제된 청구')}</td><td>${i?`<a href="#invoices/${i.id}">${esc(i.number)}</a>`:'삭제된 청구'}</td><td>${p?`<a href="#payments/${p.id}">${p.date}</a>`:'—'}</td><td>${won(a.amount)}</td><td>${badge(a.status)}</td><td>${a.status==='Active'?btn('배분 취소','reverse','danger',a.id):''}</td></tr>`})))}
function attachments(type,id){return panel('첨부파일',`<div class="panel-body"><input id="attachmentFile" type="file" accept=".pdf,.xlsx,.docx,.png,.jpg,.jpeg,.txt">${btn('파일 첨부','upload')}<p class="summary-line">PDF, XLSX, DOCX, PNG, JPG, TXT · 최대 ${boot.settings.maxAttachmentMb}MB</p></div>`+state.attachments.filter(a=>a.entityType===type&&a.entityId===id).map(a=>`<div class="attachment-item"><a href="/api/attachments/${a.id}">↧ ${esc(a.originalFileName)}</a><small>${Math.ceil(a.fileSize/1024)} KB</small>${btn('삭제','delete-attachment','danger',a.id)}</div>`).join(''))}
async function loadHistory(){const id=selectedId,t=entityType();const rows=await api(`/audit/${t}/${id}`);if(selectedId!==id||!$('#historyRows'))return;$('#historyRows').outerHTML=`<div id="historyRows">${rows.length?rows.map(a=>`<div class="audit-row"><b>${esc(a.action)}</b> ${esc(a.reason)}<small>${new Date(a.occurredAtUtc).toLocaleString('ko-KR')} · ${esc(a.actorType)} / ${esc(a.source)} · 추적 ${esc(a.correlationId.slice(0,8))}</small><details><summary>변경 전후 보기</summary><pre class="audit-json">변경 전: ${esc(a.oldValueJson)}\n변경 후: ${esc(a.newValueJson)}</pre></details></div>`).join(''):empty('변경 이력이 없습니다.','')}</div>`}
const options=(items,selected)=>items.map(([value,label])=>`<option value="${esc(value)}" ${String(value)===String(selected)?'selected':''}>${esc(label)}</option>`).join('');
function field(label,name,value='',type='text',attrs=''){const isMoney=type==='number'&&['unitPrice','discountAmount','amount','value','taxVat','taxTotal','purchaseSupply','purchaseVat'].includes(name);if(isMoney){const min=(attrs.match(/min="([^"]+)"/)||[])[1]||'0',step=(attrs.match(/step="([^"]+)"/)||[])[1]||'any';return `<label class="field">${label}<input name="${name}" type="text" inputmode="decimal" data-money data-money-min="${min}" data-money-step="${step}" value="${esc(formatMoneyValue(value))}" ${attrs}></label>`}return `<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${attrs}></label>`}
function select(label,name,items,value=''){return `<label class="field">${label}<select name="${name}">${options(items,value)}</select></label>`}
function customerSelect(value){return select('거래처 *','customerId',state.customers.filter(c=>c.isActive||c.id===value).map(c=>[c.id,(c.isPreferred?'★ 주거래처 · ':'')+c.companyName]),value)}
function orderSelect(value){return select('수주 *','orderId',state.orders.filter(o=>o.status==='Open').map(o=>[o.id,o.projectName+' · '+o.number]),value)}
function openModal(title,body,onSubmit,submitLabel='저장'){const d=$('#modal');$('#modalBody').innerHTML=`<form id="modalForm"><div class="modal-head"><h2>${title}</h2><button type="button" class="icon" data-action="close-modal" aria-label="닫기">×</button></div><div class="form-body">${body}<div class="modal-error" role="alert" hidden></div></div><div class="modal-foot"><button type="button" data-action="close-modal">닫기</button><button type="submit" class="primary">${submitLabel}</button></div></form>`;$('#modalForm').addEventListener('submit',async e=>{e.preventDefault();const submit=e.submitter,error=d.querySelector('.modal-error');error.hidden=true;submit.disabled=true;try{await onSubmit(new FormData(e.target));d.close();await refresh()}catch(e){error.textContent=e.message;error.hidden=false;error.scrollIntoView({block:'nearest'});}finally{submit.disabled=false}});d.querySelectorAll("input[data-money]").forEach(validateMoneyInput);d.showModal()}
function customerModal(id){const c=state.customers.find(x=>x.id===id)||{};openModal(id?'거래처 수정':'새 거래처',`<div class="fields">${field('상호 *','companyName',c.companyName,'text','required maxlength="200"')}${field('사업자번호','businessNumber',c.businessNumber,'text','maxlength="12"')}${field('대표자','ceoName',c.ceoName)}${field('담당자','contactName',c.contactName)}${field('연락처','phone',c.phone)}${field('이메일','email',c.email,'email')}${field('업태','businessType',c.businessType)}${field('종목','businessItem',c.businessItem)}${field('주소','address',c.address)}${select('사용 여부','isActive',[['true','사용'],['false','사용 안 함']],c.isActive??true)}<label class="check" style="grid-column:1/-1"><input name="isPreferred" type="checkbox" ${c.isPreferred?'checked':''}> ★ 주거래처로 지정</label><label class="field full">메모<textarea name="memo">${esc(c.memo)}</textarea></label></div>`,async fd=>{const data=Object.fromEntries(fd);data.version=c.version||1;data.isActive=data.isActive==='true';data.isPreferred=fd.has('isPreferred');const result=await api('/customers'+(id?'/'+id:''),data,id?'PUT':'POST');location.hash='customers/'+result.id;toast('거래처를 저장했습니다.')})}
function lineItem(i={description:'',quantity:1,unitPrice:0,discountAmount:0,taxCategory:'Taxable',unit:'식',specification:'',vatRate:.1}){return `<div class="item-block"><div class="line-item">${field('품목 *','description',i.description,'text','required maxlength="1000"')}${field('수량','quantity',i.quantity,'number','required min="0.0001" step="0.0001"')}${field('단가','unitPrice',i.unitPrice,'number','required min="0" step="0.0001"')}${field('정액 할인','discountAmount',i.discountAmount,'number','min="0" step="0.0001"')}${select('세금 구분','taxCategory',[['Taxable','과세'],['Exempt','면세'],['ZeroRated','영세율']],i.taxCategory)}<button type="button" data-action="remove-line">×</button></div><div class="fields">${field('규격','specification',i.specification)}${field('단위','unit',i.unit)}</div></div>`}
function readDocument(form){const fd=new FormData(form),data=Object.fromEntries(fd);return {customerId:Number(data.customerId),projectName:data.projectName,date:data.date,dueDate:data.dueDate||null,siteName:data.siteName,memo:data.memo,items:[...form.querySelectorAll('.item-block')].map(el=>{const val=n=>el.querySelector(`[name="${n}"]`).value;return {description:val('description'),quantity:Number(val('quantity')),unitPrice:moneyInputNumber(val('unitPrice')),discountAmount:moneyInputNumber(val('discountAmount')||0),taxCategory:val('taxCategory'),unit:val('unit'),specification:val('specification'),vatRate:.1}}),policy:{taxMode:data.taxMode,roundingMode:data.roundingMode,vatCalculationUnit:data.vatCalculationUnit,calculationPolicyVersion:1}}}
function documentModal(kind,id){if(!state.customers.some(c=>c.isActive)){toast('거래처를 먼저 등록해 주세요.',true);return}const d=state.quotations.find(x=>kind==='quotations'&&x.id===id)||{};const p=d.policyJson?JSON.parse(d.policyJson):boot.settings.defaultPolicy||{};const items=d.itemsJson?JSON.parse(d.itemsJson).map(x=>x.input):[undefined];openModal(kind==='orders'?'직접 수주 등록':id?'견적 초안 수정':'새 견적 초안',`<div class="fields">${customerSelect(d.customerId)}${field('프로젝트명 *','projectName',d.projectName,'text','required maxlength="300"')}${field('작성일 *','date',d.date||state.today,'date','required')}${field(kind==='orders'?'납기':'견적 유효기간','dueDate',d.dueDate,'date')}${field('현장','siteName',d.siteName)}${select('부가세 입력','taxMode',[['Exclusive','부가세 별도'],['Inclusive','부가세 포함']],p.taxMode)}${select('원 단위 처리','roundingMode',[['Floor','버림'],['Round','반올림']],p.roundingMode)}${select('VAT 계산 단위','vatCalculationUnit',[['Document','문서 전체'],['Item','품목별']],p.vatCalculationUnit)}</div><div id="lineItems">${items.map(i=>lineItem(i)).join('')}</div>${btn('＋ 품목 추가','add-line')}${btn('금액 계산','calculate')}<div id="calcResult" class="calculation">저장 시 서버에서 금액을 계산합니다.</div><label class="field">메모<textarea name="memo">${esc(d.memo)}</textarea></label>`,async fd=>{const data=readDocument($('#modalForm'));data.expectedVersion=d.version||0;const result=await api('/'+kind+(id?'/'+id:''),data,id?'PUT':'POST');location.hash=kind+'/'+result.id;toast('문서를 저장했습니다.')});$('#lineItems').parentElement.querySelectorAll('button[data-action]').forEach(b=>b.type='button')}
function invoiceModal(orderId){if(!state.orders.some(o=>o.status==='Open')){toast('진행 중인 수주를 먼저 등록해 주세요.',true);return}openModal('청구 등록',`<div class="fields">${orderSelect(orderId)}${select('청구 유형','invoiceType',Object.entries(types).filter(([k])=>['Deposit','Interim','Final','General','Additional'].includes(k)),'Deposit')}${field('청구일 *','date',state.today,'date','required')}${field('지급기한 (선택)','dueDate','','date')}${select('금액 지정 방식','basis',[['percentage','계약 공급가액의 비율 (%)'],['amount','공급가액 직접 입력']])}${field('비율 또는 공급가액','value',30,'number','min="0.0001" step="0.0001"')}</div><div class="notice">최종 잔금 청구는 남은 공급가액과 VAT를 각각 사용해 차액을 맞춥니다. 저장하면 청구와 미수금에 바로 반영됩니다.</div>`,async fd=>{const d=Object.fromEntries(fd),o=order(Number(d.orderId)),final=d.invoiceType==='Final';const result=await api('/invoices',{orderId:o.id,invoiceType:d.invoiceType,date:d.date,dueDate:d.dueDate||null,amount:!final&&d.basis==='amount'?moneyInputNumber(d.value):null,percentage:!final&&d.basis==='percentage'?moneyInputNumber(d.value):null,expectedVersion:o.version,idempotencyKey:crypto.randomUUID()});location.hash='invoices/'+result.id;toast('청구를 저장하고 미수금에 반영했습니다.')});$('[name=invoiceType]').addEventListener('change',e=>{$('[name=value]').disabled=e.target.value==='Final';$('[name=basis]').disabled=e.target.value==='Final'})}
function editInvoiceModal(id){const i=state.invoices.find(x=>x.id===id);const allocatedAmount=allocated('invoice',id);openModal('청구 수정',`<div class="notice">저장하면 청구와 미수금에 바로 반영됩니다. 현재 배분 입금: ${won(allocatedAmount)}. 부가세는 수주 기준으로 계산합니다.${i.taxInvoiceIssued?'<br><b>외부에서 발급한 세금계산서는 자동으로 수정되지 않습니다. 원본도 확인하세요.</b>':''}</div><div class="fields">${select('청구 유형','invoiceType',Object.entries(types).filter(([k])=>['Deposit','Interim','Final','General','Additional'].includes(k)),i.invoiceType)}${field('청구일 *','date',i.date,'date','required')}${field('지급기한 (선택)','dueDate',i.dueDate,'date')}${field('공급가액 *','amount',i.supplyAmount,'number','required min="1" step="1"')}</div><label class="field">수정 사유 *<textarea name="reason" required maxlength="1000"></textarea></label>`,async fd=>{await api('/invoices/'+id,{invoiceType:fd.get('invoiceType'),date:fd.get('date'),dueDate:fd.get('dueDate')||null,supplyAmount:moneyInputNumber(fd.get('amount')),expectedVersion:i.version,idempotencyKey:crypto.randomUUID(),reason:fd.get('reason')},'PUT');toast('청구를 수정했습니다.')},'수정 저장')}
function deleteInvoiceModal(id){const i=state.invoices.find(x=>x.id===id);openModal('청구 삭제',`<div class="notice">${esc(i.number)} · ${won(i.totalAmount)} 청구를 목록에서 삭제하고 미수금에서 제외합니다. 변경 이력과 첨부파일은 보관됩니다.${i.taxInvoiceIssued?'<br><b>외부에서 발급한 세금계산서는 자동으로 취소되지 않습니다.</b>':''}<br>입금 배분이 있다면 먼저 배분을 취소해 주세요.</div><label class="field">삭제 사유 *<textarea name="reason" required maxlength="1000"></textarea></label>`,async fd=>{await api('/invoices/'+id+'/delete',{expectedVersion:i.version,idempotencyKey:crypto.randomUUID(),reason:fd.get('reason')});location.hash='invoices';toast('청구를 삭제했습니다.')},'삭제')}
function linkPaymentModal(id){const p=state.payments.find(x=>x.id===id),rows=state.orders.filter(o=>o.status==='Open'&&o.customerId===p.customerId);if(!rows.length){toast('같은 거래처의 진행 중인 프로젝트가 없습니다.',true);return}openModal('기존 입금을 프로젝트에 연결',`<div class="notice">${cname(p.customerId)} · 입금액 ${won(p.amount)}<br>저장하면 선택한 프로젝트의 잔금에 반영됩니다.</div><div class="fields">${select('프로젝트 *','orderId',[['','프로젝트 선택'],...rows.map(o=>[o.id,o.projectName+' · '+o.number])],'')}</div>`,async fd=>{const idValue=Number(fd.get('orderId'));if(!idValue)throw Error('프로젝트를 선택해 주세요.');await api('/payments/'+id+'/project',{orderId:idValue,expectedVersion:p.version,idempotencyKey:crypto.randomUUID()});toast('기존 입금을 프로젝트에 연결했습니다.')},'연결 저장')}
function editPaymentModal(id){const p=state.payments.find(x=>x.id===id),linked=allocated('payment',id),rows=state.orders.filter(o=>o.status==='Open'&&o.customerId===p.customerId);const project=linked>0?'<div class="notice">이전 청구에 배분된 입금입니다. 프로젝트나 금액을 바꾸려면 기존 배분을 먼저 취소해 주세요. 날짜와 기타 정보는 수정할 수 있습니다.</div>':select('프로젝트 *','orderId',[['','프로젝트 선택'],...rows.map(o=>[o.id,o.projectName+' · '+o.number])],p.orderId||'');openModal('입금 수정',`<div class="notice">${cname(p.customerId)} · 저장하면 프로젝트 잔금에 바로 반영됩니다.</div><div class="fields">${project}${field('입금일 *','date',p.date,'date','required')}${field('입금액 *','amount',p.amount,'number',linked>0?'required min="1" step="1" readonly':'required min="1" step="1"')}${field('은행','bankName',p.bankName)}${field('입금자 / 참조','reference',p.reference)}<label class="field full">메모<textarea name="memo">${esc(p.memo)}</textarea></label></div>`,async fd=>{const orderId=linked>0?null:Number(fd.get('orderId'));if(!linked&&!orderId)throw Error('프로젝트를 선택해 주세요.');await api('/payments/'+id,{orderId,date:fd.get('date'),amount:moneyInputNumber(fd.get('amount')),bankName:fd.get('bankName'),reference:fd.get('reference'),memo:fd.get('memo'),expectedVersion:p.version,idempotencyKey:crypto.randomUUID()},'PUT');toast('입금을 수정하고 반영했습니다.')},'수정 저장')}
function paymentModal(){const rows=state.orders.filter(o=>o.status==='Open');if(!rows.length){toast('진행 중인 프로젝트를 먼저 등록해 주세요.',true);return}openModal('프로젝트 입금 등록',`<div class="notice">프로젝트와 입금액을 확인하고 저장하면 프로젝트 잔금에 바로 반영됩니다.</div><div class="fields">${select('프로젝트 *','orderId',[['','프로젝트 선택'],...rows.map(o=>[o.id,o.projectName+' · '+(customer(o.customerId)?.companyName||'')])],'')}${field('실제 입금일 *','date',state.today,'date','required')}${field('입금액 *','amount','','number','required min="1" step="1"')}${field('은행','bankName')}${field('입금자 / 참조','reference')}<label class="field full">메모<textarea name="memo"></textarea></label></div>`,async fd=>{const o=order(Number(fd.get('orderId')));if(!o)throw Error('프로젝트를 선택해 주세요.');const data=Object.fromEntries(fd);data.orderId=o.id;data.customerId=o.customerId;data.amount=moneyInputNumber(data.amount);data.idempotencyKey=crypto.randomUUID();const p=await api('/payments',data);location.hash='payments/'+p.id;toast('입금을 프로젝트에 반영했습니다.')})}
function workModal(orderId,id){const w=state.fulfillments.find(x=>x.id===id)||{};if(!state.orders.some(o=>o.status==='Open')){toast('진행 중인 수주가 없습니다.',true);return}openModal(id?'작업 수정':'납품 · 작업 등록',`<div class="fields">${orderSelect(w.orderId||orderId)}${select('작업 종류','type',Object.entries(types).filter(([k])=>!['Deposit','Interim','Final','General','Additional'].includes(k)),w.type||'Delivery')}${field('작업 내용 (선택)','description',w.description,'text','maxlength="2000"')}${select('상태','status',[['Planned','예정'],['InProgress','진행 중'],['Completed','완료'],['Cancelled','취소']],w.status||'Planned')}${field('예정일 (선택)','plannedDate',w.plannedDate,'date')}${field('완료일 (선택)','completedDate',w.completedDate,'date')}${field('수량 (선택)','quantity',w.quantity,'number','min="0.0001" step="0.0001"')}<label class="field full">메모<textarea name="memo">${esc(w.memo)}</textarea></label></div>`,async fd=>{const d=Object.fromEntries(fd);d.orderId=Number(d.orderId);d.quantity=d.quantity?Number(d.quantity):null;d.plannedDate=d.plannedDate||null;d.completedDate=d.completedDate||null;d.version=w.version||1;await api('/fulfillments'+(id?'/'+id:''),d,id?'PUT':'POST');toast('작업을 저장했습니다.')})}
async function allocateModal(id){const p=state.payments.find(x=>x.id===id),items=state.invoices.filter(i=>i.customerId===p.customerId&&i.status==='Confirmed'&&due(i)>0);if(!items.length){toast('같은 거래처의 미수 청구가 없습니다.',true);return}const suggestion=await api('/payments/'+id+'/suggest');openModal('입금을 청구에 배분',`<div class="notice">${cname(p.customerId)} · 입금액 ${won(p.amount)} · 미배분액 ${won(unallocated(p))}<br>프로젝트와 청구를 확인해 선택하세요. 여러 청구에 나눠 배분하려면 한 건씩 배분해 주세요.</div><div class="fields">${select('대상 청구','invoiceId',items.map(i=>[i.id,(order(i.orderId)?.projectName||i.projectName)+' · '+i.number+' · 미수 '+won(due(i))]),items[0].id)}${field('배분금액 *','amount',Math.min(unallocated(p),due(items[0])),'number','required min="1" step="1"')}</div><p class="summary-line">지급기한 순 제안: ${suggestion.candidates.map(x=>esc(x.number)+' '+won(x.amount)).join(', ')||'없음'}</p>`,async fd=>{const i=state.invoices.find(x=>x.id===Number(fd.get('invoiceId'))),amount=moneyInputNumber(fd.get('amount'));await api('/allocations',{paymentId:p.id,invoiceId:i.id,amount,expectedVersion:p.version,invoiceVersion:i.version,idempotencyKey:crypto.randomUUID()});toast('입금을 배분했습니다.')},'배분 승인 및 저장');$('[name=invoiceId]').addEventListener('change',e=>{{const input=$('[name=amount]');input.value=formatMoneyValue(Math.min(unallocated(p),due(items.find(i=>i.id===Number(e.target.value)))));validateMoneyInput(input)}})}
function approval(title,text,path,row,reason=false){openModal(title,`<div class="notice">${text}</div>${reason?'<label class="field">사유 *<textarea name="reason" required maxlength="1000"></textarea></label>':''}`,async fd=>{const result=await api(path,{expectedVersion:row.version,idempotencyKey:crypto.randomUUID(),reason:fd.get('reason')||''});if(path.endsWith('/convert'))location.hash='orders/'+result.id;toast('처리했습니다.')},'승인하고 반영')}
function settingsPage(){const s=boot.settings,p=s.defaultPolicy||{};return heading('워크스페이스 설정','회사 정보, 계산 정책, AI 연결과 데이터 보호를 관리합니다.','','PREFERENCES')+`<section class="panel settings-section"><h3>회사 정보 · 기본 계산 정책</h3><form id="settingsForm"><div class="fields">${field('회사명','companyName',s.companyName,'text','required')}${field('사업자번호','businessNumber',s.businessNumber)}${field('주소','address',s.address)}${field('연락처','phone',s.phone)}${select('부가세 입력','taxMode',[['Exclusive','별도'],['Inclusive','포함']],p.taxMode)}${select('원 단위 처리','roundingMode',[['Floor','버림'],['Round','반올림']],p.roundingMode)}${select('VAT 계산 단위','vatCalculationUnit',[['Document','문서 전체'],['Item','품목별']],p.vatCalculationUnit)}${field('첨부 크기 제한 (MB)','maxAttachmentMb',s.maxAttachmentMb,'number','min="1" max="50"')}</div>${btn('설정 저장','save-settings','primary')}</form><p class="summary-line">계산 정책 변경은 새 문서에 적용됩니다. 기존 문서의 거래처 스냅샷과 금액은 유지됩니다.</p></section><section class="panel settings-section"><h3>AI 연결</h3><div class="notice">이 PC의 ChatGPT 로그인은 Codex를 통해 사용할 수 있습니다. ChatGPT 연결을 선택하면 API 키를 입력하지 않아도 됩니다.</div><div class="fields">${select('연결 방식','aiConnectionMode',[['Auto','자동 선택'],['ChatGpt','ChatGPT 로그인 (Codex)'],['Api','AI API 키 사용']],s.aiConnectionMode||'Auto')}${field('ChatGPT 모델 (비우면 기본 모델)','chatGptModel',s.chatGptModel||'')}${field('Chat Completions 호환 HTTPS 주소','aiEndpoint',s.aiEndpoint,'url','placeholder="https://서비스주소/v1/chat/completions"')}${field('모델명','aiModel',s.aiModel)}${field('API 키 (암호화 저장)','apiKey','','password',`autocomplete="off" placeholder="${boot.aiConfigured?'저장됨 · 변경할 때만 입력':'API 키 입력'}"`)}${select('AI 초안 생성 권한','aiDraftsEnabled',[['false','조회만 허용'],['true','조회 및 초안 허용']],s.aiDraftsEnabled)}</div><p class="summary-line">질문과 필요한 업무 데이터가 선택한 AI로 전송됩니다. 첨부파일은 보내기를 눌렀을 때 분석용 이미지로 전송됩니다.</p>${btn('AI 설정 저장','save-ai','primary')}</section><section class="panel settings-section"><h3>MCP 외부 AI 연결</h3><label class="check"><input id="mcpEnabled" type="checkbox" ${s.mcpEnabled?'checked':''}> 로컬 MCP 연결 활성화</label><div class="actions" style="margin-top:17px">${btn('연결 설정 저장','save-mcp')}${btn('주소 · 토큰 보기','show-mcp')}</div><div id="mcpInfo"></div></section><section class="panel settings-section"><h3>엑셀 백업 · 복원</h3><p class="summary-line">백업 위치: ${esc(boot.dataRoot)}\\Backup<br>실행 중 하루 1회 자동으로 엑셀 백업을 저장합니다. 파일에는 첨부 원본과 복원 정보가 포함됩니다.<br>복원 정보가 유지되도록 백업 파일을 엑셀에서 편집하지 마세요.</p><div class="actions">${btn('엑셀 백업 만들기','backup','primary')}${btn('저장 폴더 열기','open-folder')}${btn('프로그램 종료','shutdown','danger')}</div><div id="backupList" style="margin-top:20px"></div></section>`}
async function loadBackups(){const rows=await api('/backups');if(!$('#backupList'))return;$('#backupList').innerHTML=table(['백업 시각','파일','크기',''],rows.map(b=>`<tr><td>${new Date(b.createdAtUtc).toLocaleString('ko-KR')}</td><td><a href="/api/backups/${encodeURIComponent(b.name)}">${esc(b.name)}</a></td><td>${Math.ceil(b.size/1024)} KB</td><td>${btn('복원','restore','',esc(b.name))} ${btn('삭제','delete-backup','danger',esc(b.name))}</td></tr>`))}
async function action(name,id,el){switch(name){case 'refresh':await refresh();toast('최신 자료를 불러왔습니다.');break;case 'toggle-ai':$('#aiPanel').hidden=!$('#aiPanel').hidden;localStorage.setItem('imorder.ai.hidden',String($('#aiPanel').hidden));if(typeof aiRefreshStatus==='function')aiRefreshStatus();break;case 'close-modal':$('#modal').close();break;case 'new-purchase':purchaseOrderModal();break;case 'edit-purchase':purchaseOrderModal(Number(id));break;case 'purchase-receipt':purchaseReceiptModal(Number(id));break;case 'purchase-bill':purchaseBillModal(Number(id));break;case 'purchase-payment':purchasePaymentModal(Number(id));break;case 'cancel-purchase':purchaseCancelModal('order',Number(id));break;case 'purchase-cancel-entry':{const [kind,key]=id.split(':');purchaseCancelModal(kind,Number(key));break;}case 'new-customer':customerModal();break;case 'edit-customer':customerModal(Number(id));break;case 'delete-customer':{const c=state.customers.find(x=>x.id===Number(id));openModal('거래처 삭제',`<div class="notice"><b>${esc(c.companyName)}</b> 거래처를 삭제합니다.<br>연결된 견적·수주·청구·입금이 있으면 삭제할 수 없습니다. 첨부파일은 목록에서 숨기고 보관합니다.</div>`,async()=>{await api(`/customers/${c.id}/delete`,{expectedVersion:c.version,idempotencyKey:crypto.randomUUID(),reason:'사용자 요청'});location.hash='customers';toast('거래처를 삭제했습니다.')},'삭제');break;}case 'new-quotation':documentModal('quotations');break;case 'edit-quotation':documentModal('quotations',Number(id));break;case 'new-order':documentModal('orders');break;case 'new-invoice':invoiceModal(Number(id)||null);break;case 'edit-invoice':editInvoiceModal(Number(id));break;case 'delete-invoice':deleteInvoiceModal(Number(id));break;case 'purchase-tax-import':$('#aiPanel').hidden=false;localStorage.setItem('imorder.ai.hidden','false');$('#chatInput').value='첨부한 매입 세금계산서를 읽고 공급처, 날짜, 공급가액, 부가세, 승인번호가 포함된 매입 입력안을 만들어 줘. 세금계산서만으로 지급 완료로 처리하지 말아 줘.';$('#chatInput').focus();if(typeof aiRefreshStatus==='function')aiRefreshStatus();$('#aiFileInput').click();break;case 'tax-invoice-import':$('#aiPanel').hidden=false;localStorage.setItem('imorder.ai.hidden','false');$('#chatInput').value='첨부한 매출 세금계산서를 읽고 청구 입력안을 만들어 줘';$('#chatInput').focus();if(typeof aiRefreshStatus==='function')aiRefreshStatus();$('#aiFileInput').click();break;case 'new-payment':paymentModal();break;case 'edit-payment':editPaymentModal(Number(id));break;case 'link-payment':linkPaymentModal(Number(id));break;case 'new-fulfillment':workModal(Number(id)||null);break;case 'edit-fulfillment':workModal(null,Number(id));break;case 'work-attachments':workAttachmentsModal(Number(id));break;case 'add-line':$('#lineItems').insertAdjacentHTML('beforeend',lineItem());break;case 'remove-line':if(document.querySelectorAll('.item-block').length>1)el.closest('.item-block').remove();break;case 'calculate':{const result=await api('/calculate',readDocument($('#modalForm')));$('#calcResult').innerHTML=`공급 ${won(result.supplyAmount)}　 VAT ${won(result.vatAmount)}　 <strong>합계 ${won(result.totalAmount)}</strong>`;break}case 'approve-quotation':{const q=state.quotations.find(x=>x.id===Number(id));approval('견적 승인',`${esc(q.number)} · ${won(q.totalAmount)}<br>승인 후 이 견적의 금액과 품목을 수정할 수 없습니다.`, `/quotations/${id}/approve`,q);break}case 'convert-quotation':{const q=state.quotations.find(x=>x.id===Number(id));approval('수주 전환',`${esc(q.projectName)} · ${won(q.totalAmount)}<br>현재 견적의 금액과 거래처 정보를 수주에 보존합니다.`,`/quotations/${id}/convert`,q);break}case 'confirm-invoice':{const i=state.invoices.find(x=>x.id===Number(id));approval('청구 확정',`${cname(i.customerId)} · ${esc(i.number)}<br>공급 ${won(i.supplyAmount)} + VAT ${won(i.vatAmount)} = <b>${won(i.totalAmount)}</b><br>지급기한 ${i.dueDate||'미지정'} · 누적 청구에 반영합니다.`,`/invoices/${id}/confirm`,i);break}case 'confirm-payment':{const p=state.payments.find(x=>x.id===Number(id));approval('입금 확정',`${cname(p.customerId)} · ${p.date} · <b>${won(p.amount)}</b><br>확정 후 청구에 배분할 수 있습니다.`,`/payments/${id}/confirm`,p);break}case 'close-order':{const o=order(Number(id));approval('수주 종료','전체 미수금과 미청구 금액이 모두 0원인지 확인합니다. 납품·작업 기록은 필수가 아닙니다.',`/orders/${id}/close`,o);break}case 'order-details':orderDetailsModal(Number(id));break;case 'contract-change':contractModal(Number(id));break;case 'tax-record':taxModal(Number(id));break;case 'reopen-order':approval('수주 재개','수주를 진행 중 상태로 되돌립니다.',`/orders/${id}/reopen`,order(Number(id)),true);break;case 'allocate':await allocateModal(Number(id));break;case 'reverse':{const a=state.allocations.find(x=>x.id===Number(id));approval('입금 배분 취소',`${won(a.amount)} 배분을 역처리합니다. 원본 이력을 보존하고 미배분액과 청구 미수금을 복원합니다.`,`/allocations/${id}/reverse`,a,true);break}case 'cancel-document':{const row=state[view].find(x=>x.id===Number(id));approval('문서 취소','연결된 활성 입금 배분이 있다면 먼저 배분을 취소해야 합니다. 취소 기록은 이력에 남습니다.',`/cancel/${entityType()}/${id}`,row,true);break}case 'upload':{const file=$('#attachmentFile').files[0];if(!file)throw Error('첨부할 파일을 선택해 주세요.');const f=new FormData();f.append('file',file);await api(`/attachments/${entityType()}/${selectedId}`,f);await refresh();toast('파일을 첨부했습니다.');break}case 'delete-attachment':{const a=state.attachments.find(x=>x.id===Number(id));approval('첨부 삭제',`${esc(a.originalFileName)} 파일을 목록에서 숨깁니다. 보관 파일은 유지됩니다.`,`/attachments/${id}/delete`,a,true);break}case 'save-settings':{const f=Object.fromEntries(new FormData($('#settingsForm')));boot.settings=await api('/settings',{...boot.settings,companyName:f.companyName,businessNumber:f.businessNumber,address:f.address,phone:f.phone,maxAttachmentMb:Number(f.maxAttachmentMb),defaultPolicy:{taxMode:f.taxMode,roundingMode:f.roundingMode,vatCalculationUnit:f.vatCalculationUnit,calculationPolicyVersion:1}},'PUT');toast('설정을 저장했습니다.');break}case 'save-ai':{const val=n=>$(`[name=${n}]`).value;boot.settings=await api('/settings',{...boot.settings,aiConnectionMode:val('aiConnectionMode'),chatGptModel:val('chatGptModel'),aiEndpoint:val('aiEndpoint'),aiModel:val('aiModel'),aiDraftsEnabled:val('aiDraftsEnabled')==='true'},'PUT');if(val('apiKey')){await api('/secrets/ai',{value:val('apiKey')});boot.aiConfigured=true;$('[name=apiKey]').value=''}toast('AI 연결 설정을 저장했습니다.');if(typeof aiRefreshStatus==='function')aiRefreshStatus();break}case 'save-mcp':boot.settings=await api('/settings',{...boot.settings,mcpEnabled:$('#mcpEnabled').checked},'PUT');toast('MCP 설정을 저장했습니다.');break;case 'show-mcp':{const info=await api('/mcp-info');$('#mcpInfo').innerHTML=`<p class="summary-line">Bearer 인증을 지원하는 MCP 클라이언트에서 사용하세요. 이 토큰은 외부에 공유하지 마세요.</p><div class="settings-key">주소: ${esc(info.url)}<br>Authorization: Bearer ${esc(info.token)}</div>`;break}case 'backup':await api('/backups',{});await loadBackups();toast('엑셀 백업을 만들었습니다. 파일 이름을 누르면 내려받을 수 있습니다.');break;case 'delete-backup':openModal('엑셀 백업 삭제',`<div class="notice">${esc(id)}<br>선택한 백업 파일이 영구 삭제되며 복원할 수 없습니다. 현재 업무자료는 삭제되지 않습니다.</div>${field('확인하려면 삭제를 입력하세요','confirm','','text','required pattern="삭제"')}`,async()=>{await api(`/backups/${encodeURIComponent(id)}/delete`,{});toast('선택한 백업 파일을 삭제했습니다.')},'백업 삭제');break;case 'restore':openModal('백업 복원',`<div class="notice">${esc(id)}<br>현재 자료를 엑셀로 백업한 뒤 선택한 시점의 자료와 첨부파일로 교체합니다. 계속하려면 아래에 ‘복원’을 입력해 주세요.</div>${field('복원 확인','confirm','','text','required pattern="복원"')}`,async()=>{await api(`/backups/${encodeURIComponent(id)}/restore`,{});boot=await api('/bootstrap');toast('백업을 복원했습니다.')},'복원 실행');break;case 'shutdown':openModal('프로그램 종료','<div class="notice">저장한 자료는 유지됩니다. 다시 사용하려면 ImCompany.exe를 실행하세요.</div>',async()=>{await api('/shutdown',{});toast('프로그램을 종료했습니다. 이 창을 닫아 주세요.');},'종료');break;case 'open-folder':{const result=await api('/open-data-folder',{});if(result.opened)toast('엑셀 백업 폴더를 열었습니다.');else toast('폴더 창을 찾을 수 없습니다. 파일 탐색기에서 백업 위치를 직접 열어 주세요.',true);break}}}
document.addEventListener('click',async e=>{const go=e.target.closest('[data-go]');if(go){location.hash=go.dataset.go;return}const el=e.target.closest('[data-action]');if(!el)return;e.preventDefault();if(el.disabled)return;el.disabled=true;try{await action(el.dataset.action,el.dataset.id,el)}catch(e){toast(e.message,true)}finally{el.disabled=false}});
window.addEventListener('hashchange',route);
(async()=>{try{boot=await api('/bootstrap');route();await refresh();window.dispatchEvent(new Event('imorder-ready'))}catch(e){$('#content').innerHTML=empty('프로그램에 연결할 수 없습니다.',esc(e.message));toast(e.message,true)}})();
